		/** 
		 * Tests creating a new Payment.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Payment");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Payment" );

			try {            
				Payment entity = PaymentService.getPaymentInstance().createPayment( generateNewEntity() );
				thePrimaryKey = entity.getPaymentId();
				LOGGER.info( "-- Successfully created a Payment with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Payment. 
		 */
		public Payment testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Payment" );

			Payment entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Payment with primary key" );
			msg.append( thePrimaryKey );
			
			PaymentFetchOneSummary fetchOneSummary = new PaymentFetchOneSummary( thePrimaryKey );

			try {
				entity = PaymentService.getPaymentInstance().getPayment( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Payment " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Payment.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Payment." );

			StringBuilder msg = new StringBuilder( "Failed to update a Payment : " );        
			Payment entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Payment." );

				// for use later on...
				thePrimaryKey = entity.getPaymentId();

				PaymentService proxy = PaymentService.getPaymentInstance();            
				proxy.updatePayment( entity );   

				LOGGER.info( "-- Successfully saved Payment - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Payment.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Payment." );

			try{
			    Payment entity = testRead(); 
				PaymentService.getPaymentInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Payment with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Payment with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Payments.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Payments:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Payment : " );        
			List<Payment> collection  = null;

			try {
				// call the static get method on the PaymentService
				collection = PaymentService.getPaymentInstance().getAllPayment();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Payment entity = null;            
					Iterator<Payment> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getPaymentId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

